class Solution {
public:
    int findTilt(TreeNode* root) {
        long long total = 0;
        dfs(root, total);
        return static_cast<int>(total);
    }
private:
    int dfs(TreeNode* node, long long& total) {
        if (!node) return 0;
        int leftSum = dfs(node->left, total);
        int rightSum = dfs(node->right, total);
        total += abs(leftSum - rightSum);
        return node->val + leftSum + rightSum;
    }
};
